#!/usr/bin/env node
// @ts-check
// Conventional Commits check for PR titles (the squash-merge subject) and commit subjects.
// Usage: PR_TITLE="feat(diagrams): …" node .github/scripts/conventional-commits.mjs <base-sha> <head-sha>

import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

export const TYPES = [
  "feat",
  "fix",
  "docs",
  "style",
  "refactor",
  "perf",
  "test",
  "build",
  "ci",
  "chore",
  "revert",
];

const SUBJECT = new RegExp(`^(${TYPES.join("|")})(\\([a-z0-9][a-z0-9-]*\\))?!?: \\S.{0,99}$`);

/**
 * @param {string} subject first line of a commit message or a PR title
 * @returns {string | undefined} why the subject is invalid, or undefined when valid
 */
export function checkSubject(subject) {
  if (/^(Merge|Revert ") /.test(subject)) return undefined; // generated by git/GitHub
  if (SUBJECT.test(subject)) return undefined;
  return `"${subject}" is not "<type>(<scope>)?: <description>" with type one of ${TYPES.join(", ")} (max 100 chars after the colon)`;
}

function main() {
  const [base, head] = process.argv.slice(2);
  const problems = [];
  const title = process.env.PR_TITLE;
  if (title !== undefined) {
    const problem = checkSubject(title);
    if (problem) problems.push(`PR title: ${problem}`);
  }
  if (base && head) {
    const log = execFileSync("git", ["log", "--format=%H %s", `${base}..${head}`], {
      encoding: "utf8",
    });
    for (const line of log.split("\n").filter(Boolean)) {
      const [sha, ...rest] = line.split(" ");
      const problem = checkSubject(rest.join(" "));
      if (problem) problems.push(`${sha.slice(0, 7)}: ${problem}`);
    }
  }
  for (const p of problems) console.error(`::error::${p}`);
  if (problems.length > 0) process.exit(1);
  console.log("Conventional Commits: OK");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main();
